let x = BigInt(input);

// Normalize angle to [0, 360)
const mod = (a, m) => {
    let r = a % m;
    if (r < 0n) r += m;
    return r;
};

const full = 360n;
const ninety = 90n;

let bestTurns = 0;
let bestDev = 360n; // larger than any possible deviation

for (let k = 0n; k < 4n; k++) {
    // total rotation of image: camera rotation is -x (since camera CW => image CCW)
    // FPGA adds k*90 CW => net = k*90 - x (CW)
    let total = k * ninety - x;
    total = mod(total, full);

    // deviation from vertical is minimal of angle and 360-angle
    let dev = total <= full - total ? total : full - total;

    if (dev < bestDev) {
        bestDev = dev;
        bestTurns = k;
    }
}

console.log(String(bestTurns));

